   339→        /// <summary>
   340→        /// Validates the transaction, in a static manner (i.e. without accesing state/storage).
   341→        /// It basically ensures the transaction is well formed (i.e. no null values where not allowed, no overflows, etc).
   342→        /// As a part of validating the transaction the premium per gas will be calculated, to save computation this
   343→        /// is returned in an out parameter.
   344→        /// </summary>
   345→        /// <param name="tx">The transaction to validate</param>
   346→        /// <param name="header">The block containing the transaction. Only BaseFee is being used from the block atm.</param>
   347→        /// <param name="spec">The release spec with which the transaction will be executed</param>
   348→        /// <param name="opts">Options (Flags) to use for execution</param>
   349→        /// <param name="intrinsicGas">Calculated intrinsic gas</param>
   350→        /// <param name="floorGas"></param>
   351→        /// <returns></returns>
   352→        protected virtual TransactionResult ValidateStatic(
   353→            Transaction tx,
   354→            BlockHeader header,
   355→            IReleaseSpec spec,
   356→            ExecutionOptions opts,
   357→            in IntrinsicGas intrinsicGas)
   358→        {
   359→
   360→            bool validate = !opts.HasFlag(ExecutionOptions.SkipValidation);
   361→
   362→            if (tx.SenderAddress is null)
   363→            {
   364→                TraceLogInvalidTx(tx, "SENDER_NOT_SPECIFIED");
   365→                return TransactionResult.SenderNotSpecified;
   366→            }
   367→
   368→            if (validate && tx.Nonce >= ulong.MaxValue - 1)
   369→            {
   370→                // we are here if nonce is at least (ulong.MaxValue - 1). If tx is contract creation,
   371→                // it is max possible value. Otherwise, (ulong.MaxValue - 1) is allowed, but ulong.MaxValue not.
   372→                if (tx.IsContractCreation || tx.Nonce == ulong.MaxValue)
   373→                {
   374→                    TraceLogInvalidTx(tx, "NONCE_OVERFLOW");
   375→                    return TransactionResult.NonceOverflow;
   376→                }
   377→            }
   378→
   379→            if (tx.IsAboveInitCode(spec))
   380→            {
   381→                TraceLogInvalidTx(tx, $"CREATE_TRANSACTION_SIZE_EXCEEDS_MAX_INIT_CODE_SIZE {tx.DataLength} > {spec.MaxInitCodeSize}");
   382→                return TransactionResult.TransactionSizeOverMaxInitCodeSize;
   383→            }
   384→
   385→            return ValidateGas(tx, header, intrinsicGas.MinimalGas, validate);
   386→        }
   387→
   388→        protected virtual TransactionResult ValidateGas(Transaction tx, BlockHeader header, long minGasRequired, bool validate)
   389→        {
   390→            if (tx.GasLimit < minGasRequired)
   391→            {
   392→                TraceLogInvalidTx(tx, $"GAS_LIMIT_BELOW_INTRINSIC_GAS {tx.GasLimit} < {minGasRequired}");
   393→                return TransactionResult.GasLimitBelowIntrinsicGas;
   394→            }
   395→
   396→            if (validate && tx.GasLimit > header.GasLimit - header.GasUsed)
   397→            {
   398→                TraceLogInvalidTx(tx, $"BLOCK_GAS_LIMIT_EXCEEDED {tx.GasLimit} > {header.GasLimit} - {header.GasUsed}");
   399→                return TransactionResult.BlockGasLimitExceeded;
   400→            }
   401→
   402→            return TransactionResult.Ok;
   403→        }
   404→
   405→        // TODO Should we remove this already
   406→        protected virtual bool RecoverSenderIfNeeded(Transaction tx, IReleaseSpec spec, ExecutionOptions opts, in UInt256 effectiveGasPrice)
   407→        {
   408→            bool deleteCallerAccount = false;
   409→            Address? sender = tx.SenderAddress;
   410→            if (sender is null || !WorldState.AccountExists(sender))
   411→            {
   412→                bool commit = opts.HasFlag(ExecutionOptions.Commit) || !spec.IsEip658Enabled;
   413→                bool restore = opts.HasFlag(ExecutionOptions.Restore);
   414→                bool noValidation = opts.HasFlag(ExecutionOptions.SkipValidation);
   415→
   416→                if (Logger.IsDebug) Logger.Debug($"TX sender account does not exist {sender} - trying to recover it");
   417→
   418→                // hacky fix for the potential recovery issue
   419→                if (tx.Signature is not null)
   420→                    tx.SenderAddress = Ecdsa.RecoverAddress(tx, !spec.ValidateChainId);
   421→
   422→                if (sender != tx.SenderAddress)
   423→                {
   424→                    if (Logger.IsWarn) Logger.Warn($"TX recovery issue fixed - tx was coming with sender {sender} and the now it recovers to {tx.SenderAddress}");
   425→                    sender = tx.SenderAddress;
   426→                }
   427→                else
   428→                {
   429→                    TraceLogInvalidTx(tx, $"SENDER_ACCOUNT_DOES_NOT_EXIST {sender}");
   430→                    if (!commit || noValidation || effectiveGasPrice.IsZero)
   431→                    {
   432→                        deleteCallerAccount = !commit || restore;
   433→                        WorldState.CreateAccount(sender, in UInt256.Zero);
   434→                    }
   435→                }
   436→
   437→                if (sender is null)
   438→                {
   439→                    ThrowInvalidDataException($"Failed to recover sender address on tx {tx.Hash} when previously recovered sender account did not exist.");
   440→                }
   441→            }
   442→
   443→            return deleteCallerAccount;
   444→        }
